mutations.find:
units = shas.map((sha) => ({
      range: [`${sha}^`, sha],
      message: git(['log', '-1', '--format=%B', sha]).toString('utf8'),
      ref: sha,
    }))

mutations.replace:
units = shas.map((sha) => ({
      range: [`${sha}^`, sha],
      message: shas.map((s) => git(['log', '-1', '--format=%B', s]).toString('utf8')).join('\n'),
      ref: sha,
    }))
